            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, period, g) {
            if (this.ROUND_OF[g] <= period) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _run(dec, k) {
            var c = this.C;
            var per = [];
            var clar = c.CL0;
            var cumh = 0.0;
            var cumk = 0.0;
            var p, i;
            for (p = 1; p <= 4; p++) {
                var a = {};
                for (i = 0; i < this.KEYS.length; i++) { a[this.KEYS[i]] = this._active(dec, p, this.KEYS[i]); }
                var m = this.MUESTRA[a.muestra1];
                var g = this.GUION[a.guion1];
                var n = (p >= 3) ? this.NOTAS[a.notas3] : this.NOTAS.memoria;
                var cu = (p >= 2) ? this.CUMPLIDO[a.cumplido2] : this.CUMPLIDO.celebrar;
                var kk = (p >= 2) ? this.COMPROMISO[a.compromiso2] : this.COMPROMISO.ninguno;
                var d = (p >= 3) ? this.DATOS[a.datos3] : this.DATOS.notas;
                var pr = (p === 4) ? this.PROBLEMA[a.problema4] : [0.0, 0.0, 0.0];
                var inf = (p === 4) ? this.INFORME[a.informe4] : [0.0, 0.0, 1.0, 0.0];
                var conv = m[0] * g[0];
                var relevant = conv * m[1];
                var q = this._clamp(m[2] * g[1] * n[0] * cu[0] * d[1], c.Q_MIN, c.Q_MAX);
                var facts = relevant * c.FACTS * q;
                cumh += facts;
                var pol = m[3] + g[2] + cu[1];
                var fp = this._clamp(pol * n[1] * kk[1], c.FP_MIN, c.FP_MAX);
                var cq = Math.min(c.CQ_MAX, q / c.CQ_REF);
                var commit = (relevant * kk[0] * cq + inf[1]) * inf[2];
                cumk += commit;
                var ev = Math.min(1.0, cumh / c.HNEED);
                clar = clar + c.K_H * facts + n[2] + kk[2];
                var clarShow = this._clamp(this._clamp(clar + pr[0] + pr[1] * ev, 0.0, 100.0) + inf[0], 0.0, 100.0);
                var trust = this._clamp(c.T0 + m[4] + g[3] + cu[2] + kk[3] + d[0] + pr[2] + inf[3], 0.0, 100.0);
                var hard = 0;
                if (p >= 3 && a.datos3 === 'oculta') { hard += 1; }
                if (p === 4 && a.informe4 === 'inflar') { hard += 1; }
                per.push({ conv: conv, relevant: relevant, q: q, facts: facts, fp: fp, commit: commit, clar: clarShow,
                           trust: trust, hard: hard, a: a });
                if (p >= k) { break; }
            }
            var last = per[per.length - 1];
            return { per: per, q: last.q, fp: last.fp, commit: last.commit, clar: last.clar, trust: last.trust,
                     cumFacts: cumh, cumCommit: cumk, hard: last.hard, a: last.a };
        }

        _components(r) {
            var c = this.C;
            var sv = this._clamp((r.q - c.S_LO) / (c.S_HI - c.S_LO), 0, 1);
            var e = this._clamp((c.E_LO - r.fp) / (c.E_LO - c.E_HI), 0, 1);
            var u = this._clamp((r.commit - c.U_LO) / (c.U_HI - c.U_LO), 0, 1);
            var h = this._clamp((r.clar - c.H_LO) / (c.H_HI - c.H_LO), 0, 1);
            var k = this._clamp((r.trust - c.K_LO) / (c.K_HI - c.K_LO), 0, 1);
            return [sv, e, u, h, k];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._run(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_S, c.W_E, c.W_U, c.W_H, c.W_K];
            var tw = 0, num = 0, i;
            for (i = 0; i < 5; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.PERIOD_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'es') ? '.' : ',';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + ((this._lang() === 'es') ? ',' : '.') + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _fmtPct(n) {
            return (this._lang() === 'es') ? (this._fmtDec(n) + ' %') : (this._fmtDec(n) + '%');
        }

        _sum(arr) {
            var s = 0, i;
            for (i = 0; i < arr.length; i++) { s += arr[i]; }
            return s;
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var cH = ds.convHistory || [];
            var rH = ds.relevantHistory || [];
            var fH = ds.factsHistory || [];
            var qH = ds.qualityHistory || [];
            var pH = ds.falseYesHistory || [];
            var kH = ds.commitHistory || [];
            var lH = ds.clarityHistory || [];
            var tH = ds.trustHistory || [];
            var n = cH.length;
            this._set('convDisplay', n ? this._fmtInt(cH[n - 1]) : '-');
            this._set('relDisplay', n ? this._fmtInt(rH[n - 1]) : '-');
            this._set('factsDisplay', n ? (this._fmtInt(fH[n - 1]) + ' · ' + this._t('txt_total') + ' ' + this._fmtInt(ds.factsTotal || 0)) : '-');
            this._set('qualDisplay', n ? this._fmtPct(qH[n - 1]) : '-');
            this._set('fpDisplay', n ? this._fmtPct(pH[n - 1]) : '-');
            this._set('commitDisplay', n ? (this._fmtInt(kH[n - 1]) + ' · ' + this._t('txt_total') + ' ' + this._fmtInt(ds.commitTotal || 0)) : '-');
            this._set('clarDisplay', n ? this._fmtInt(lH[n - 1]) : '-');
            this._set('trustDisplay', n ? this._fmtInt(tH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var maps = {
                muestra1: { amigos: 'fb_mu_amigos', encuesta: 'fb_mu_encuesta', mercado: 'fb_mu_mercado', contadores: 'fb_mu_contadores' },
                guion1: { pitch: 'fb_gu_pitch', pasado: 'fb_gu_pasado', cuestionario: 'fb_gu_cuestionario', libre: 'fb_gu_libre' },
                cumplido2: { celebrar: 'fb_cu_celebrar', redirigir: 'fb_cu_redirigir', descuento: 'fb_cu_descuento', maqueta: 'fb_cu_maqueta' },
                compromiso2: { ninguno: 'fb_co_ninguno', siguiente: 'fb_co_siguiente', preventa: 'fb_co_preventa', carta: 'fb_co_carta' },
                notas3: { memoria: 'fb_no_memoria', textual: 'fb_no_textual', codificadas: 'fb_no_codificadas', votos: 'fb_no_votos' },
                datos3: { notas: 'fb_da_notas', consentimiento: 'fb_da_consentimiento', oculta: 'fb_da_oculta', publicar: 'fb_da_publicar' },
                problema4: { original: 'fb_pr_original', evidencia: 'fb_pr_evidencia', ampliar: 'fb_pr_ampliar', funcion: 'fb_pr_funcion' },
                informe4: { plan: 'fb_in_plan', evidencia: 'fb_in_evidencia', inflar: 'fb_in_inflar', abandonar: 'fb_in_abandonar' }
            };
            return (maps[g] && maps[g][v]) ? maps[g][v] : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._run(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

