            return {
                qualityChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Calidad de la evidencia (%)', data: [], borderColor: '#0f4c5c', backgroundColor: 'rgba(15,76,92,0.12)', borderWidth: 2 },
                            { label: '«Sí» de cortesía (%)', data: [], borderColor: '#9a3412', backgroundColor: 'rgba(154,52,18,0.12)', borderWidth: 2 },
                            { label: 'Claridad del problema', data: [], borderColor: '#1d5c3a', backgroundColor: 'rgba(29,92,58,0.12)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 110 } } }
                },
                scoreChart: {
