        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var qualityHistory = ds.qualityHistory || [];
            var falseYesHistory = ds.falseYesHistory || [];
            var clarityHistory = ds.clarityHistory || [];
            var scoreHistory = ds.scoreHistory || [];
            var self = this;
            var labels = qualityHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); });
            return {
                qualityChart: {
                    labels: labels,
                    datasets: [
                        { data: qualityHistory.slice(), label: this._t('chart_qual') },
                        { data: falseYesHistory.slice(), label: this._t('chart_fp') },
                        { data: clarityHistory.slice(), label: this._t('chart_clar') }
                    ]
                },
                scoreChart: {
                    labels: scoreHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); }),
                    datasets: [
