        getHistoryTableConfig() {
            var self = this;
            var pct = function(v) { return self._fmtPct(v); };
            var intf = function(v) { return self._fmtInt(v); };
            return [
                { key: 'results.conv', label: 'Conversaciones', i18nKey: 'col_conv', formatter: intf },
                { key: 'results.rel', label: 'Con el problema', i18nKey: 'col_rel', formatter: intf },
                { key: 'results.facts', label: 'Hechos registrados', i18nKey: 'col_facts', formatter: intf },
                { key: 'results.qual', label: 'Calidad de la evidencia (%)', i18nKey: 'col_qual', formatter: pct },
                { key: 'results.fp', label: '«Sí» de cortesía (%)', i18nKey: 'col_fp', formatter: pct },
                { key: 'results.commit', label: 'Compromisos', i18nKey: 'col_commit', formatter: intf },
                { key: 'results.clar', label: 'Claridad del problema (0–100)', i18nKey: 'col_clar', formatter: intf },
                { key: 'results.trust', label: 'Confianza (0–100)', i18nKey: 'col_trust', formatter: intf },
                { key: 'results.roundScore', label: 'Puntuación de la ronda', i18nKey: 'col_score' }
            ];
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var m = this._run(this._flat(state, mm), mm);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var d = this._flat(state, mm);
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
            if (m.hard > 0) { insights.push(this._t('cm_cap')); }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                facts: Math.round(m.cumFacts),
                qual: Math.round(m.q * 1000) / 10,
                fp: Math.round(m.fp * 1000) / 10,
                commit: Math.round(m.cumCommit),
                clar: Math.round(m.clar),
                trust: Math.round(m.trust),
                hard: m.hard,
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ej2260-cm">'
                + '<div class="ej2260-cm-score">' + score + '<span class="ej2260-cm-max">/100</span></div>'
                + '<div class="ej2260-cm-verdict">' + (s.performanceLabel || '') + '</div>'
                + '<div class="ej2260-cm-kpis">'
                + '<div class="ej2260-cm-kpi">' + this._t('cm_kpi_facts') + ' <strong>' + this._fmtInt(s.facts || 0) + '</strong></div>'
                + '<div class="ej2260-cm-kpi">' + this._t('cm_kpi_qual') + ' <strong>' + this._fmtPct(s.qual || 0) + '</strong></div>'
                + '<div class="ej2260-cm-kpi">' + this._t('cm_kpi_fp') + ' <strong>' + this._fmtPct(s.fp || 0) + '</strong></div>'
                + '<div class="ej2260-cm-kpi">' + this._t('cm_kpi_commit') + ' <strong>' + this._fmtInt(s.commit || 0) + '</strong></div>'
                + '<div class="ej2260-cm-kpi">' + this._t('cm_kpi_clar') + ' <strong>' + this._fmtInt(s.clar || 0) + '</strong></div>'
                + '<div class="ej2260-cm-kpi">' + this._t('cm_kpi_trust') + ' <strong>' + this._fmtInt(s.trust || 0) + '</strong></div>'
                + '</div>'
                + '<div class="ej2260-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ej2260-cm-insights">' + items + '</ul>'
                + '</div>';
        }

